const pptxgen = require("pptxgenjs");
let pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';

// Define Masters
pres.defineSlideMaster({
  title: 'MASTER_DARK',
  background: { color: '1E2761' },
});

pres.defineSlideMaster({
  title: 'MASTER_LIGHT',
  background: { color: 'F8F9FA' },
});

// SLIDE 1: Title (Dark)
let s1 = pres.addSlide({ masterName: 'MASTER_DARK' });
s1.addText("Developer Workforce &\nCompensation Trends", { x: 1, y: 1.5, w: 8, h: 1.5, fontSize: 44, color: "FFFFFF", bold: true, align: "left" });
s1.addText("2024 Stack Overflow Survey", { x: 1, y: 3.0, w: 8, h: 0.8, fontSize: 24, color: "CADCFC", bold: false, align: "left" });
s1.addText("65,437 respondents across 180+ countries", { x: 1, y: 4.0, w: 8, h: 0.5, fontSize: 18, color: "FFFFFF", align: "left" });
s1.addText("Source: survey.stackoverflow.co/2024/work", { x: 1, y: 4.8, w: 8, h: 0.3, fontSize: 12, color: "CADCFC", align: "left" });

// SLIDE 2: Employment Status (Light)
let s2 = pres.addSlide({ masterName: 'MASTER_LIGHT' });
s2.addText("84% of Developers Are Working, but Full-Time Employment Dips in the U.S.", { x: 0.5, y: 0.3, w: 9, h: 0.8, fontSize: 22, color: "1E2761", bold: true });

s2.addChart(pres.charts.BAR, [{
  name: "Global Employment",
  labels: ["Full-time", "Freelance / Independent", "Student"],
  values: [69.0, 16.4, 13.2]
}], {
  x: 0.5, y: 1.5, w: 5, h: 3.5, barDir: "col",
  chartColors: ["1E2761", "3B82F6", "CADCFC"],
  showValue: true, dataLabelColor: "1E2761", dataLabelPosition: "outEnd",
  catAxisLabelColor: "1E2761", valAxisLabelColor: "1E2761",
  valGridLine: { color: "E2E8F0", size: 0.5 }, catGridLine: { style: "none" },
  showLegend: false, title: "Global Employment Status (%)", showTitle: true, titleColor: "1E2761"
});

const makeShadow = () => ({ type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.15 });

s2.addShape(pres.shapes.RECTANGLE, { x: 6, y: 1.5, w: 3.5, h: 3.5, fill: { color: "FFFFFF" }, shadow: makeShadow() });
s2.addText("U.S. Market Shift", { x: 6.2, y: 1.8, w: 3.1, h: 0.5, fontSize: 18, bold: true, color: "1E2761" });
s2.addText("Full-time employment in the U.S. dropped significantly year-over-year:", { x: 6.2, y: 2.3, w: 3.1, h: 0.8, fontSize: 14, color: "333333" });
s2.addText("69.0%", { x: 6.2, y: 3.2, w: 1.1, h: 0.8, fontSize: 28, bold: true, color: "1E2761", align: "center" });
s2.addText("2023", { x: 6.2, y: 3.9, w: 1.1, h: 0.4, fontSize: 14, color: "666666", align: "center" });
s2.addText("→", { x: 7.3, y: 3.2, w: 0.9, h: 0.8, fontSize: 28, color: "333333", align: "center" });
s2.addText("64.8%", { x: 8.2, y: 3.2, w: 1.1, h: 0.8, fontSize: 28, bold: true, color: "F96167", align: "center" });
s2.addText("2024", { x: 8.2, y: 3.9, w: 1.1, h: 0.4, fontSize: 14, color: "666666", align: "center" });

// SLIDE 3: Work Environment Shift
let s3 = pres.addSlide({ masterName: 'MASTER_LIGHT' });
s3.addText("In-Person Work Rises to 20% While Hybrid Holds Steady at 42%", { x: 0.5, y: 0.3, w: 9, h: 0.8, fontSize: 22, color: "1E2761", bold: true });

s3.addChart(pres.charts.BAR, [{
  name: "2024 Environment",
  labels: ["Hybrid", "Remote", "In-Person"],
  values: [42, 38, 20]
}], {
  x: 0.5, y: 1.5, w: 4.5, h: 3.5, barDir: "col",
  chartColors: ["CADCFC", "3B82F6", "1E2761"],
  showValue: true, dataLabelColor: "1E2761", dataLabelPosition: "outEnd",
  catAxisLabelColor: "1E2761", valAxisLabelColor: "1E2761",
  valGridLine: { color: "E2E8F0", size: 0.5 }, catGridLine: { style: "none" },
  showLegend: false, title: "2024 Work Arrangements (%)", showTitle: true, titleColor: "1E2761"
});

s3.addShape(pres.shapes.RECTANGLE, { x: 5.5, y: 1.5, w: 4, h: 3.5, fill: { color: "FFFFFF" }, shadow: makeShadow() });
s3.addText("In-Person Trend", { x: 5.8, y: 1.8, w: 3.4, h: 0.5, fontSize: 18, bold: true, color: "1E2761" });
s3.addChart(pres.charts.LINE, [{
  name: "In-Person", labels: ["2022", "2023", "2024"], values: [15, 16, 20]
}], {
  x: 5.8, y: 2.3, w: 3.4, h: 2.5, lineSize: 3, lineSmooth: true,
  chartColors: ["F96167"], showValue: true, showLegend: false,
  catAxisLabelColor: "1E2761", valAxisLabelColor: "1E2761",
  valGridLine: { color: "E2E8F0", size: 0.5 }, catGridLine: { style: "none" }
});

// SLIDE 4: Salary by Developer Type
let s4 = pres.addSlide({ masterName: 'MASTER_LIGHT' });
s4.addText("Senior Executives and Dev Advocates Top $124K+ Median Salary", { x: 0.5, y: 0.3, w: 9, h: 0.8, fontSize: 22, color: "1E2761", bold: true });
s4.addImage({ path: "/app/benchmark/assets/figure_1.jpg", x: 1, y: 1.2, w: 8, h: 4, sizing: { type: 'contain', w: 8, h: 4 } });

// SLIDE 5: Experience vs. Salary
let s5 = pres.addSlide({ masterName: 'MASTER_LIGHT' });
s5.addText("Experience Pays: Top Roles Combine 14+ Years with Six-Figure Salaries", { x: 0.5, y: 0.3, w: 9, h: 0.8, fontSize: 22, color: "1E2761", bold: true });
s5.addImage({ path: "/app/benchmark/assets/figure_2.jpg", x: 1, y: 1.2, w: 8, h: 4, sizing: { type: 'contain', w: 8, h: 4 } });

